<template>
  <div><PageHeader eyebrow="ADMIN · IDENTITY" title="Tổ chức" description="Cập nhật tên hiển thị của organization hiện tại; mã tổ chức là định danh bất biến." /><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><section v-if="organization" class="panel"><div class="grid-two"><div class="list-compact-item"><div><strong>Mã tổ chức</strong><span>{{ organization.code }}</span></div><StatusPill :value="organization.status" /></div><div class="list-compact-item"><div><strong>Khởi tạo</strong><span>{{ formatDateTime(organization.createdAt) }}</span></div></div></div><form class="inline-form" style="margin-top:16px" @submit.prevent="save"><div class="form-field"><label>Tên hiển thị</label><input v-model.trim="name" class="form-input" required /></div><button class="button primary" :disabled="busy">Lưu thay đổi</button></form></section><div v-else class="loading-state">Đang tải tổ chức…</div></div>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import PageHeader from '../../../shared/ui/PageHeader.vue'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import { identityApi } from '../../../shared/api/client'; import { formatDateTime, type Organization } from '../../../shared/types'; const organization = ref<Organization | null>(null); const name = ref(''); const loading = ref(true); const busy = ref(false); const error = ref(''); async function load() { try { organization.value = await identityApi.organization(); name.value = organization.value.name } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được tổ chức.') } finally { loading.value = false } }; async function save() { busy.value = true; try { organization.value = await identityApi.updateOrganization(name.value) } catch (cause) { error.value = String((cause as Error)?.message || 'Không cập nhật được tổ chức.') } finally { busy.value = false } }; onMounted(load)
</script>
